#Ce programme permet d'extraire une phrase dans un tableau

from numpy import *

T1 = array([str] * 20)

def Saisie():
    b = False
    while not b:
        ph = input("Donner la phrase sans espace superflu ni ponctuation: ")
        b = verif(ph)
    return ph

def verif(ch):
    ok = ch.find("  ") == -1
    i = -1
    while ok and i < len(ch) - 1:
        i += 1
        ok = ch[i] not in {",", ";", "?", "!"}
    return ok

def Remplir_T1(ph):
    nb = 0
    i = 0
    S = ph + " "
    while S.find(" ") != -1:
        p = S.find(" ")
        T1[i] = S[0:p]
        S = S[p + 1:]
        if (len(S[0:p]) > nb):
            nb = len(S[0:p])
        i += 1
    return i, nb

def Afficher(T1, n):
    for i in range(n):
        print(T1[i])
